pub(super) fn from_type_guid(guid: &str) -> Option<DesignFeatureKind> {
    FAMILIES
        .iter()
        .find(|(registered, _)| registered.eq_ignore_ascii_case(guid))
        .map(|(_, kind)| kind.clone())
}
